// ===== Diffusion Photos Discord — RSS (Airtable « rss photo ») → Discord =====
// Optimisé quota Airtable (16/09) : check groupé (1 appel), marquage groupé (1 appel),
// liste des flux en cache 12 h, cron 3×/jour, pause auto si quota épuisé (429).
const CONFIG = {
  airtableToken: 'AIRTABLE_TOKEN_MASKED',
  baseId: 'appLn9VCOlsdLdp1U',            // base « rss photo »
  feedsTableId: 'tblHHzzA0AR8tHlZi',      // table des flux photos
  photosTableId: 'tblnovgnUfrGiK6zH',     // table de marquage « Photos envoyées »
  discordWebhook: 'DISCORD_WEBHOOK_MASKED', // webhook par défaut si un flux n'a pas de salon
  maxParFlux: 5,                          // anti-flood : 5 max par flux et par run
  maxParRun: 10,                          // plafond global de photos envoyées par run
  maxCandidats: 20,                       // plafond de liens vérifiés par run (formule OR)
  fenetresHeures: 48,                     // on ne considère que les articles < 48 h
  cacheFluxMs: 12 * 3600 * 1000,          // liste des flux rechargée toutes les 12 h

  // --- mapping des champs (adapte ici si les noms diffèrent) ---
  champsFlux: { nom: 'Name', url: 'rss', salon: 'Salon discord' },  // champ salon absent → fallback webhook par défaut
  champsPhotos: { lien: 'Lien', sources: 'Sources', titres: 'Titres', sommaire: 'Sommaire',
                  date: 'Date publication', salon: 'Salon Discord', image: 'Image' },
};

const decodeEntities = (s) => (s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(d))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#0?39;|&apos;|&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ').trim();

const pick = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i'));
  return m ? m[1].trim() : '';
};

function imgOf(block) {
  let m = block.match(/<media:(?:content|thumbnail)[^>]*url="([^"]+)"/i);
  if (m) return m[1].trim();
  m = block.match(/<enclosure[^>]*url="([^"]+)"[^>]*type="image[^"]*"/i) ||
      block.match(/<enclosure[^>]*type="image[^"]*"[^>]*url="([^"]+)"/i);
  if (m) return m[1].trim();
  const content = pick(block, 'content:encoded') || pick(block, 'description') || pick(block, 'summary');
  m = content.match(/<img[^>]*src="([^"]+)"/i) || content.match(/<img[^>]*src='([^']+)'/i);
  return m ? m[1].trim() : '';
}

function parseFeed(xml) {
  const items = [];
  const blocks = [...xml.matchAll(/<(?:item|entry)[\s>][\s\S]*?<\/(?:item|entry)>/gi)];
  for (const b of blocks) {
    const block = b[0];
    const title = decodeEntities(pick(block, 'title'));
    let link = pick(block, 'link');
    if (!link) { const lm = block.match(/<link[^>]*href="([^"]+)"/i); if (lm) link = lm[1].trim(); }
    if (!link) continue;
    const description = decodeEntities(pick(block, 'description') || pick(block, 'summary') || pick(block, 'content'));
    const pub = pick(block, 'pubDate') || pick(block, 'published') || pick(block, 'updated') || '';
    let isoDate = pub ? new Date(pub).toISOString() : new Date().toISOString();
    if (isNaN(new Date(isoDate).getTime())) isoDate = new Date().toISOString();
    items.push({ title, link, description, isoDate, image: imgOf(block) });
  }
  return items;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// --- exécution ---
const F = CONFIG.champsFlux, P = CONFIG.champsPhotos;
const H = { Authorization: `Bearer ${CONFIG.airtableToken}`, 'Content-Type': 'application/json' };
const base = `https://api.airtable.com/v0/${CONFIG.baseId}`;
const sd = $getWorkflowStaticData('global');

// pause quota : si 429 récent, on ne consomme RIEN pendant 24 h
if (sd.quotaPauseUntil && Date.now() < sd.quotaPauseUntil) {
  return [{ json: { workflow: 'Diffusion Photos Discord', skipped: 'quota Airtable en pause jusqu\u2019à ' + new Date(sd.quotaPauseUntil).toISOString() } }];
}

const surQuota = (e) => e && (e.statusCode === 429 || /\b429\b/.test(String(e.message || '')));

// 1) flux (cache 12 h → ~2 appels/jour au lieu de 48)
let feeds = sd.feeds;
if (!feeds || !feeds.length || Date.now() - (sd.feedsAt || 0) > CONFIG.cacheFluxMs) {
  feeds = [];
  let offset;
  do {
    const r = await this.helpers.httpRequest({ url: `${base}/${CONFIG.feedsTableId}`, headers: H, json: true });
    feeds = feeds.concat((r.records || []).map((rec) => ({
      nom: rec.fields[F.nom] || 'flux sans nom',
      url: rec.fields[F.url],
      salon: rec.fields[F.salon] || CONFIG.discordWebhook || '',
    })));
    offset = r.offset;
    if (offset) await sleep(250);
  } while (offset);
  sd.feeds = feeds; sd.feedsAt = Date.now();
}

// 2) collecte RSS (gratuit) + candidats < 48 h, triés du plus récent au plus ancien
const limite = Date.now() - CONFIG.fenetresHeures * 3600 * 1000;
let candidats = [];
const rapport = [];
for (const feed of feeds) {
  const entree = { feed: feed.nom, trouves: 0, envoyes: 0, marques: 0, dejaVus: 0, erreurs: [] };
  rapport.push(entree);
  try {
    const raw = await this.helpers.httpRequest({
      url: feed.url, method: 'GET', headers: { 'User-Agent': 'n8n-rss-discord' }, json: false,
    });
    const text = typeof raw === 'string' ? raw : (raw && raw.body ? String(raw.body) : String(raw));
    const articles = parseFeed(text).filter((a) => new Date(a.isoDate).getTime() >= limite);
    entree.trouves = articles.length;
    for (const a of articles) candidats.push({ ...a, feed });
  } catch (e) {
    entree.erreurs.push('RSS: ' + String(e.message || e));
  }
}
candidats.sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate));
candidats = candidats.slice(0, CONFIG.maxCandidats);
if (!candidats.length) {
  return [{ json: { workflow: 'Diffusion Photos Discord', flux: feeds.length, candidats: 0, rapport } }];
}

// 3) check groupé : 1 SEUL appel Airtable pour tous les candidats
let vus = new Set();
try {
  const esc = (s) => s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  const formula = 'OR(' + candidats.map((a) => `{${P.lien}}='${esc(a.link)}'`).join(',') + ')';
  const chk = await this.helpers.httpRequest({
    url: `${base}/${CONFIG.photosTableId}`, headers: H, json: true,
    qs: { filterByFormula: formula, maxRecords: 100 },
  });
  vus = new Set((chk.records || []).map((rec) => rec.fields[P.lien]).filter(Boolean));
} catch (e) {
  if (surQuota(e)) {
    sd.quotaPauseUntil = Date.now() + 24 * 3600 * 1000;
    return [{ json: { workflow: 'Diffusion Photos Discord', skipped: 'quota Airtable épuisé (429) — pause 24 h', rapport } }];
  }
  throw e;
}

// 4) nouveautés avec caps (par flux + global)
const nouveaux = [];
const parFlux = {};
for (const c of candidats) {
  if (vus.has(c.link)) continue;
  parFlux[c.feed.nom] = (parFlux[c.feed.nom] || 0) + 1;
  if (parFlux[c.feed.nom] > CONFIG.maxParFlux) continue;
  if (nouveaux.length >= CONFIG.maxParRun) break;
  nouveaux.push(c);
}
if (!nouveaux.length) {
  return [{ json: { workflow: 'Diffusion Photos Discord', flux: feeds.length, candidats: candidats.length, nouveaux: 0, rapport } }];
}

// 5) image de repli (og:image/twitter:image) pour les nouveaux sans image du flux
for (const art of nouveaux) {
  if (art.image) continue;
  try {
    const page = await this.helpers.httpRequest({
      url: art.link, method: 'GET', headers: { 'User-Agent': 'n8n-rss-discord' }, json: false,
    });
    const html = typeof page === 'string' ? page : (page && page.body ? String(page.body) : String(page));
    const m = html.match(/property=["']og:image["'][^>]*content=["']([^"']+)["']/i) ||
              html.match(/content=["']([^"']+)["'][^>]*property=["']og:image["']/i) ||
              html.match(/name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i);
    if (m && m[1]) art.image = m[1].trim();
    await sleep(400);
  } catch { /* pas d'image → pas grave */ }
}

// 6) marquage groupé AVANT envoi (1 appel, ≤ 10 enregistrements) → jamais de doublon Discord
try {
  await this.helpers.httpRequest({
    url: `${base}/${CONFIG.photosTableId}`, method: 'POST', headers: H, json: true,
    body: { records: nouveaux.map((art) => ({ fields: {
      [P.lien]: art.link,
      [P.sources]: art.feed.nom,
      [P.titres]: (art.title || '').slice(0, 255),
      [P.sommaire]: art.description.slice(0, 255),
      [P.date]: art.isoDate.slice(0, 10),
      [P.salon]: art.feed.salon || '',
      [P.image]: art.image || '',
    } })) },
  });
} catch (e) {
  if (surQuota(e)) {
    sd.quotaPauseUntil = Date.now() + 24 * 3600 * 1000;
    return [{ json: { workflow: 'Diffusion Photos Discord', skipped: 'quota Airtable épuisé (429) au marquage — pause 24 h, rien envoyé', rapport } }];
  }
  throw e;
}

// 7) envoi Discord (anti-flood 400 ms)
for (const entree of rapport) {
  entree.envoyes = nouveaux.filter((a) => a.feed.nom === entree.feed).length;
  entree.marques = entree.envoyes;
}
for (const art of nouveaux) {
  const embed = {
    title: art.title.slice(0, 250) || '(sans titre)',
    url: art.link,
    description: art.description.slice(0, 350) || '',
    color: 10181046,   // violet : distingue les photos des actus (vert)
    footer: { text: art.feed.nom },
    timestamp: art.isoDate,
  };
  if (art.image) embed.image = { url: art.image };
  try {
    await this.helpers.httpRequest({
      url: art.feed.salon || CONFIG.discordWebhook, method: 'POST', json: true,
      headers: { 'Content-Type': 'application/json' },
      body: { embeds: [embed] },
    });
    await sleep(400);
  } catch (e) {
    const entree = rapport.find((r) => r.feed === art.feed.nom);
    if (entree) entree.erreurs.push('Discord: ' + String(e.message || e));
  }
}

return [{ json: { workflow: 'Diffusion Photos Discord', flux: feeds.length, candidats: candidats.length,
                  envoyes: nouveaux.length, rapport } }];
